/**
 * Pure GFM pipe-table parsing and serialization, used by Live Preview's table
 * widget (src/renderer/markdown/live-preview.ts) to turn a table block into an
 * editable model and to write that model back to the document. Reading view
 * relies on `marked`'s own GFM table support instead
 * (src/renderer/markdown/render.ts).
 *
 * This module is deliberately text-only: `parseTable` and `serializeTable` are
 * exact inverses over cell *source*, and nothing here interprets what that
 * source means. Rendering a cell's inline markdown (bold, code, wikilinks,
 * tags) is `inlineHtml`'s job in render.ts, which the widget calls per cell —
 * so cells and Reading view resolve inline syntax through one shared
 * implementation rather than two that can drift.
 *
 * Block detection (does *this* text form a table, and where does it start and
 * end in the document) is handled upstream by CodeMirror's Lezer GFM grammar,
 * which already parses `Table` syntax-tree nodes.
 */

export type Align = "left" | "center" | "right" | null;

export interface ParsedTable {
  align: Align[];
  header: string[];
  rows: string[][];
}

const DELIMITER_CELL_RE = /^:?-+:?$/;

/**
 * Splits one pipe-table row into trimmed cell strings. Honors `\|` escapes
 * (they don't act as separators) and drops a leading/trailing empty cell
 * produced by an outer `|` (e.g. `| a | b |` has no empty first/last cell).
 */
function splitRow(line: string): string[] {
  const ESCAPED_PIPE = "�";
  const protectedLine = line.trim().replace(/\\\|/g, ESCAPED_PIPE);
  let cells = protectedLine.split("|");
  if (cells.length > 1 && cells[0].trim() === "") cells = cells.slice(1);
  if (cells.length > 1 && cells[cells.length - 1].trim() === "") cells = cells.slice(0, -1);
  const restore = new RegExp(ESCAPED_PIPE, "g");
  return cells.map((c) => c.replace(restore, "|").trim());
}

function parseAlignRow(line: string): Align[] | null {
  if (!line.includes("|") && !line.includes("-")) return null;
  const cells = splitRow(line);
  if (cells.length === 0) return null;
  const aligns: Align[] = [];
  for (const cell of cells) {
    if (!DELIMITER_CELL_RE.test(cell)) return null;
    const left = cell.startsWith(":");
    const right = cell.endsWith(":");
    aligns.push(left && right ? "center" : right ? "right" : left ? "left" : null);
  }
  return aligns;
}

/**
 * Parses a GFM pipe-table block — a header line, an alignment delimiter
 * line (e.g. `| --- | :---: | ---: |`), and zero or more data rows — into
 * structured cell data. `source` should be exactly the lines making up one
 * table block (e.g. sliced from a Lezer `Table` syntax node's `[from, to)`
 * range), with no leading/trailing blank lines. Data rows are padded or
 * truncated to the header's column count, matching GFM's table spec.
 * Returns null if the first two lines don't form a valid header/delimiter
 * pair (i.e. this isn't actually a table).
 */
export function parseTable(source: string): ParsedTable | null {
  const lines = source.replace(/\r\n/g, "\n").split("\n");
  while (lines.length && lines[lines.length - 1].trim() === "") lines.pop();
  if (lines.length < 2) return null;

  if (!lines[0].includes("|")) return null;
  const header = splitRow(lines[0]);
  if (header.length === 0) return null;

  const align = parseAlignRow(lines[1]);
  if (!align) return null;
  while (align.length < header.length) align.push(null);
  align.length = header.length;

  const rows: string[][] = [];
  for (let i = 2; i < lines.length; i++) {
    if (lines[i].trim() === "") break;
    const cells = splitRow(lines[i]);
    while (cells.length < header.length) cells.push("");
    cells.length = header.length;
    rows.push(cells);
  }

  return { align, header, rows };
}

/** Escapes a literal `|` in cell text as `\|`, the inverse of splitRow's unescaping. */
function escapeCell(s: string): string {
  return s.replace(/\|/g, "\\|");
}

function delimiterCell(align: Align): string {
  switch (align) {
    case "left":
      return ":---";
    case "center":
      return ":---:";
    case "right":
      return "---:";
    default:
      return "---";
  }
}

/**
 * Serializes structured table data back to a GFM pipe-table string: a header
 * row, an alignment delimiter row honoring each column's `Align`
 * (`:---`/`:---:`/`---:`/`---`), then one row per data row. Literal `|`
 * characters in cell text are escaped as `\|`. The header's column count is
 * authoritative — the align array and every data row are padded/truncated to
 * match — so the output is always a table `parseTable` accepts. Inverse of
 * `parseTable`: `parseTable(serializeTable(t))` deep-equals `t` for any table
 * `parseTable` itself produced.
 */
export function serializeTable(table: ParsedTable): string {
  const cols = table.header.length;
  const fit = <T>(arr: T[], fill: T): T[] => {
    const out = arr.slice(0, cols);
    while (out.length < cols) out.push(fill);
    return out;
  };
  const row = (cells: string[]) => `| ${fit(cells, "").map(escapeCell).join(" | ")} |`;
  const lines = [
    row(table.header),
    `| ${fit(table.align, null as Align).map(delimiterCell).join(" | ")} |`,
    ...table.rows.map(row),
  ];
  return lines.join("\n");
}

