import type { App } from "../app";
import { parseBaseFile, runQuery, type BaseDefinition, type BaseViewDefinition, type QueryResult } from "../bases";
import { stringifyBaseFile } from "../bases/base-file-write";
import { buildExportMatrix, matrixToCsv, matrixToTsv } from "../bases/base-export";
import { valueToDisplayString } from "../bases/coerce";
import { matchesSearch } from "../bases/search-match";
import type { QueryRow } from "../bases/query-engine";
import { enumerateFrontmatterKeys, frontmatterKeyForColumn, parseEditedValue, resolveColumns } from "../bases/columns";
import { PromptModal } from "../modals/modals";
import type { TFile } from "../types";
import { buildViewHeaderNavButtons, type View } from "../workspace";
import { openFilterEditor, type FilterEditorScope } from "./bases/filter-editor";
import { patchFrontmatter, patchFrontmatterText } from "../frontmatter-io";
import { openPropertiesMenu } from "./bases/properties-menu";
import { openSortGroupMenu, type SortGroupValue } from "./bases/sort-group-menu";
import { BasesTableView, type RowHeight } from "./bases/table-view";
import { BasesCardsView } from "./bases/cards-view";
import { BasesToolbar, type ToolbarHandlers } from "./bases/toolbar";

const DEFAULT_CARD_ASPECT_RATIO = 16 / 9;
const DEFAULT_CARD_SIZE = 240;

const FILE_NAMESPACE_FIELDS = [
  "file.name",
  "file.path",
  "file.folder",
  "file.ext",
  "file.size",
  "file.ctime",
  "file.mtime",
  "file.tags",
  "file.links",
  "file.backlinks",
  "file.embeds",
];

function defaultBaseYaml(): string {
  return stringifyBaseFile({
    filters: undefined,
    formulas: {},
    properties: {},
    summaries: {},
    views: [{ type: "table", name: "Table" }],
  });
}

/**
 * The Bases view: parses a `.base` file, runs its current view's query, and
 * renders the toolbar plus the active view type (Table or Cards). File-backed
 * like `MarkdownView`, mirroring its `containerEl`/`setFile`/header structure.
 */
export class BaseView implements View {
  readonly viewType = "base";
  containerEl: HTMLElement;
  file: TFile | null = null;

  private headerEl: HTMLElement;
  private titleEl: HTMLElement;
  private bodyEl: HTMLElement;
  private errorEl: HTMLElement;

  private toolbar: BasesToolbar;
  private tableView: BasesTableView;
  private cardsView: BasesCardsView;

  private def: BaseDefinition | null = null;
  private currentViewName = "";
  private searchQuery = "";
  private rowHeights = new Map<string, RowHeight>();
  private lastColumns: string[] = [];
  private lastResult: QueryResult | null = null;
  private renderScheduled = false;
  /**
   * The exact text we last knew to be on disk for this file — set both
   * right before `persist()` writes it (predicting the write's outcome)
   * and every time `reloadFromDisk()` actually reads it. Used to make the
   * "did our own file change externally?" check idempotent against content
   * rather than a single-consume flag.
   *
   * This file's writes are echoed by up to *two* "modify" events: one
   * synchronous one from `Vault.modify()` itself, and a second, later one
   * from the main-process chokidar watcher noticing the same write on disk
   * (see `src/main/main.ts`'s `startWatcher`). A single-consume "skip the
   * next reload" flag only absorbs the first of those — the later watcher
   * echo would still trigger a real `reloadFromDisk()`, which replaces
   * `this.def` with freshly parsed objects and silently orphans any view/def
   * object reference an already-open Sort/Filter/Properties panel is still
   * holding (its next edit would land on the orphaned object and never
   * reach the file — this caused a real, reproducible flake in
   * `bases.spec.ts`). Comparing content instead is immune to however many
   * duplicate/delayed echoes arrive: if the file's current text already
   * matches what we expect, there's nothing to reload.
   */
  private lastKnownText: string | null = null;
  private pendingKnownText: string | null = null;
  private vaultSwitching = false;
  private persistRequestedWhileSuspended = false;
  private suppressReconcileModify = false;
  private sourceEdit: { file: TFile; columnPath: string; rawText: string; originalText: Promise<string> } | null = null;
  private sourceWritePath: string | null = null;
  private readonly sourcePersistsInFlight = new Set<Promise<void>>();
  private sourceConflictReadOnly = false;
  private readonly saveStatusEl: HTMLElement;
  private readonly mobileCleanups: Array<() => void> = [];

  /**
   * When set, this base is an *embedded* base (a ```base code block in a
   * note) rather than a standalone `.base` file: `this.file` is the host
   * note (supplying the `this` context and new-file folder), reads come from
   * the inline YAML, and persistence goes through this callback (which
   * rewrites the code block in the host note) instead of `vault.modify`.
   */
  private inlinePersist: ((text: string) => Promise<void>) | null = null;

  private readonly onVaultChange = (changedFile?: TFile) => {
    if (changedFile && this.file && changedFile.path === this.file.path) {
      if (this.suppressReconcileModify) {
        this.suppressReconcileModify = false;
        return;
      }
      // For an embedded base the host note's own changes must NOT be
      // re-parsed as base YAML — the inline text we hold is authoritative,
      // and our own persist writes back to that same host note (ignoring it
      // here also avoids a write→modify→reload loop).
      if (this.inlinePersist) return;
      void this.reloadIfChangedExternally();
      return;
    }
    if (changedFile && changedFile.path === this.sourceWritePath) return;
    // Some other file changed (a row's frontmatter was edited, a note was
    // created/deleted, etc.) — re-run the query against the current
    // (unchanged) `.base` definition, no need to re-parse it from disk.
    this.scheduleRerender();
  };

  /** Re-parse from disk only if the file's current content differs from what we last wrote/read — see `lastKnownText`'s doc comment. */
  private async reloadIfChangedExternally(): Promise<void> {
    if (!this.file) return;
    const cached = this.app.vault.getCachedContent(this.file.path);
    if (cached !== undefined && cached === this.lastKnownText) return;
    const text = await this.app.vault.read(this.file);
    if (text === (this.pendingKnownText ?? this.lastKnownText)) return;
    await this.applyText(text);
  }

  constructor(private app: App) {
    this.containerEl = document.createElement("div");
    this.containerEl.className = "base-view";

    this.headerEl = document.createElement("div");
    this.headerEl.className = "view-header";
    const left = document.createElement("div");
    left.className = "view-header-left";
    left.appendChild(buildViewHeaderNavButtons());
    const titleContainer = document.createElement("div");
    titleContainer.className = "view-header-title-container mod-at-start mod-fade mod-at-end";
    this.titleEl = document.createElement("div");
    this.titleEl.className = "view-header-title";
    titleContainer.appendChild(this.titleEl);
    this.headerEl.append(left, titleContainer);

    const handlers: ToolbarHandlers = {
      onSwitchView: (name) => this.switchView(name),
      onAddView: (type) => this.addView(type),
      onSetViewType: (type) => this.setViewType(type),
      onRenameView: (name) => this.renameView(name),
      onDeleteView: (name) => this.deleteView(name),
      onMoveView: (name, dir) => this.moveView(name, dir),
      onOpenFilter: (anchorEl) => this.openFilterPanel(anchorEl),
      onOpenSort: (anchorEl) => this.openSortPanel(anchorEl),
      onOpenProperties: (anchorEl) => this.openPropertiesPanel(anchorEl),
      onSearch: (query) => this.setSearchQuery(query),
      onNewFile: () => this.createNewFileInFolder(),
      onRowHeightChange: (height) => this.setRowHeight(height),
      onCopy: () => void this.copyViewToClipboard(),
      onExportCsv: () => this.exportViewAsCsv(),
    };
    this.toolbar = new BasesToolbar(app, handlers);

    this.errorEl = document.createElement("div");
    this.errorEl.className = "bases-error";
    this.errorEl.style.display = "none";

    this.tableView = new BasesTableView(app, {
      onOpenFile: (file, newTab) => void this.app.openFile(file, newTab),
      onEditCell: (file, columnPath, rawText) => this.editCell(file, columnPath, rawText),
      onEditStart: (file, columnPath, rawText) => this.beginSourceEdit(file, columnPath, rawText),
      onEditDraft: (rawText) => { if (this.sourceEdit) this.sourceEdit.rawText = rawText; },
      onEditEnd: () => { this.sourceEdit = null; },
    });

    this.cardsView = new BasesCardsView(app, {
      onOpenFile: (file, newTab) => void this.app.openFile(file, newTab),
    });

    this.bodyEl = document.createElement("div");
    this.bodyEl.className = "base-view-body";
    this.saveStatusEl = document.createElement("div");
    this.saveStatusEl.className = "bases-save-status";
    this.saveStatusEl.setAttribute("role", "status");
    this.saveStatusEl.setAttribute("aria-live", "polite");
    this.bodyEl.append(this.toolbar.containerEl, this.saveStatusEl, this.errorEl, this.tableView.containerEl, this.cardsView.containerEl);

    this.containerEl.append(this.headerEl, this.bodyEl);
    if (document.body.classList.contains("is-mobile") && window.visualViewport) {
      const viewport = window.visualViewport;
      const syncKeyboard = () => {
        const offset = Math.max(0, window.innerHeight - viewport.height - viewport.offsetTop);
        this.containerEl.style.setProperty("--bases-keyboard-offset", `${offset}px`);
        this.containerEl.querySelector<HTMLElement>(".bases-cell-input:focus")?.scrollIntoView({ block: "nearest", inline: "nearest" });
      };
      viewport.addEventListener("resize", syncKeyboard);
      viewport.addEventListener("scroll", syncKeyboard);
      this.mobileCleanups.push(
        () => viewport.removeEventListener("resize", syncKeyboard),
        () => viewport.removeEventListener("scroll", syncKeyboard),
      );
      syncKeyboard();
    }
  }

  getDisplayText(): string {
    return this.file?.basename ?? "Base";
  }

  getIcon(): string {
    return "layout-grid";
  }

  getFile(): TFile | null {
    return this.file;
  }

  /**
   * Serialized state for `WorkspaceLeaf.getViewState()` / workspace restore.
   * The `.base` file path is the whole of this view's identity — everything
   * else (active view name, filters, sort) lives in the file itself. Named
   * `file` to match the `PersistedLeaf.file` convention used for markdown and
   * canvas tabs. An *embedded* base has no tab of its own and is never
   * serialized, so the host-note case doesn't need special handling here.
   */
  getState(): { file: string | null } {
    return { file: this.file?.path ?? null };
  }

  /**
   * Restore from `getState()`. Deliberately tolerant: a `.base` file that was
   * deleted or renamed while Geode was closed leaves an empty Bases tab
   * rather than throwing out of `setViewState` (which restore does not catch
   * per-leaf).
   */
  async setState(state: unknown): Promise<void> {
    const filePath = (state as { file?: unknown } | null)?.file;
    if (typeof filePath !== "string") return;
    const file = this.app.vault.getFileByPath(filePath);
    if (!file) return;
    await this.setFile(file);
  }

  async setFile(file: TFile): Promise<void> {
    await this.persistQueue;
    await Promise.all([...this.sourcePersistsInFlight]);
    this.tableView.resetForFile();
    this.cardsView.destroy();
    this.sourceEdit = null;
    this.sourceWritePath = null;
    this.sourceConflictReadOnly = false;
    this.vaultSwitching = false;
    this.persistRequestedWhileSuspended = false;
    this.suppressReconcileModify = false;
    this.inlinePersist = null;
    this.searchQuery = "";
    this.currentViewName = "";
    this.rowHeights.clear();
    this.lastColumns = [];
    this.lastResult = null;
    this.containerEl.querySelector(".bases-conflict-state")?.remove();
    delete this.containerEl.dataset.basesConflictPath;
    this.setSaveStatus("", false);
    this.file = file;
    this.containerEl.inert = false;
    this.bodyEl.inert = false;
    this.tableView.setReadOnly(false);
    this.titleEl.textContent = file.basename;
    await this.reloadFromDisk();
  }

  /**
   * Mount this base from inline YAML — an embedded ```base code block. The
   * host note supplies the `this` context and the folder for the "New"
   * button; edits persist via `persist` (which rewrites the code block in
   * the note). Used by the Markdown renderer for embedded bases; the tab
   * header is hidden since an embed has no tab of its own.
   */
  async mountInline(
    hostFile: TFile,
    text: string,
    persist: (text: string) => Promise<void>,
    viewName?: string
  ): Promise<void> {
    this.inlinePersist = persist;
    this.file = hostFile;
    this.markEmbedded();
    if (viewName) this.currentViewName = viewName;
    await this.applyText(text);
  }

  /** Hide the tab-style header and mark the container as an embed — used when this view is embedded/transcluded inside a note. */
  markEmbedded(): void {
    this.headerEl.style.display = "none";
    this.containerEl.classList.add("bases-embed-view");
  }

  /** Select a specific view by name (used by `![[File.base#ViewName]]` transclusion); no-op if it doesn't exist. */
  selectView(name: string): void {
    if (!this.def || !this.def.views.some((v) => v.name === name)) return;
    this.currentViewName = name;
    this.runAndRender();
  }

  private async reloadFromDisk(): Promise<void> {
    if (!this.file) return;
    const text = await this.app.vault.read(this.file);
    await this.applyText(text);
  }

  /** Parse `text` (freshly read from disk) into `this.def` and re-render. Records `text` as the current known-good state (see `lastKnownText`). */
  private async applyText(text: string): Promise<void> {
    this.lastKnownText = text;
    const parsed = parseBaseFile(text);
    if ("error" in parsed) {
      this.showError(`Couldn't parse base: ${parsed.error}`);
      return;
    }
    this.def = parsed.def;
    if (this.def.views.length === 0) this.def.views.push({ type: "table", name: "Table" });
    if (document.body.classList.contains("is-mobile") && this.file) {
      const saved = localStorage.getItem(`geode:bases-view:${encodeURIComponent(this.app.vault.root)}:${encodeURIComponent(this.file.path)}`);
      if (saved && this.def.views.some((view) => view.name === saved)) this.currentViewName = saved;
    }
    if (!this.def.views.some((v) => v.name === this.currentViewName)) {
      this.currentViewName = this.def.views[0].name;
    }
    this.runAndRender();
  }

  async acceptExternalText(text: string): Promise<void> {
    await this.applyText(text);
    this.suppressReconcileModify = true;
  }

  onOpen(): void {
    this.app.vault.on("modify", this.onVaultChange);
    this.app.vault.on("create", this.onVaultChange);
    this.app.vault.on("delete", this.onVaultChange);
    this.app.metadataCache.on("changed", this.onVaultChange);
  }

  async onClose(): Promise<void> {
    await this.persistQueue;
    this.app.vault.off("modify", this.onVaultChange);
    this.app.vault.off("create", this.onVaultChange);
    this.app.vault.off("delete", this.onVaultChange);
    this.app.metadataCache.off("changed", this.onVaultChange);
    this.cardsView.destroy();
    this.sourceEdit = null;
    for (const cleanup of this.mobileCleanups.splice(0)) cleanup();
  }

  private scheduleRerender(): void {
    if (this.renderScheduled) return;
    this.renderScheduled = true;
    queueMicrotask(() => {
      this.renderScheduled = false;
      this.runAndRender();
    });
  }

  private showError(message: string): void {
    this.errorEl.textContent = message;
    this.errorEl.style.display = "";
    this.tableView.containerEl.style.display = "none";
    this.cardsView.containerEl.style.display = "none";
  }

  private clearError(): void {
    this.errorEl.style.display = "none";
    const isCards = this.currentView()?.type === "cards";
    this.tableView.containerEl.style.display = isCards ? "none" : "";
    this.cardsView.containerEl.style.display = isCards ? "" : "none";
  }

  private currentView(): BaseViewDefinition | null {
    return this.def?.views.find((v) => v.name === this.currentViewName) ?? null;
  }

  private knownPropertyKeys(): string[] {
    const files = this.app.vault.getMarkdownFiles();
    return enumerateFrontmatterKeys(files, (f) => this.app.metadataCache.getFileCache(f)?.frontmatter ?? null);
  }

  private allPropertyPaths(): string[] {
    if (!this.def) return FILE_NAMESPACE_FIELDS;
    return [
      ...FILE_NAMESPACE_FIELDS,
      ...this.knownPropertyKeys().map((k) => `note.${k}`),
      ...Object.keys(this.def.formulas).map((n) => `formula.${n}`),
    ];
  }

  private runAndRender(): void {
    if (!this.def || !this.file) return;
    const view = this.currentView();
    if (!view) return;

    const knownKeys = this.knownPropertyKeys();
    const columns = resolveColumns(view.order, knownKeys);
    this.lastColumns = columns;

    const queryColumns = view.type === "cards" && view.image && !columns.includes(view.image)
      ? [...columns, view.image]
      : columns;
    const viewForQuery: BaseViewDefinition = { ...view, order: queryColumns };
    const defForQuery: BaseDefinition = {
      ...this.def,
      views: this.def.views.map((v) => (v === view ? viewForQuery : v)),
    };

    const files = this.app.vault.getMarkdownFiles();
    const result = runQuery(defForQuery, this.currentViewName, files, this.app.vault, this.app.metadataCache, this.file, Date.now());
    if ("error" in result) {
      this.showError(result.error);
      return;
    }
    this.clearError();
    this.lastResult = result;

    this.toolbar.update({
      viewNames: this.def.views.map((v) => v.name),
      currentViewName: this.currentViewName,
      currentViewType: view.type === "cards" ? "cards" : "table",
      resultCount: result.rows.length,
      rowHeight: this.rowHeights.get(this.currentViewName) ?? "medium",
    });

    this.renderActiveView(view, result, columns);
  }

  /** Dispatch rendering to the Table or Cards view based on `view.type`, keeping only the active one visible. */
  private renderActiveView(view: BaseViewDefinition, result: QueryResult, columns: string[]): void {
    if (!this.def) return;
    const isCards = view.type === "cards";
    this.tableView.containerEl.style.display = isCards ? "none" : "";
    this.cardsView.containerEl.style.display = isCards ? "" : "none";

    if (isCards) {
      this.cardsView.render(result, {
        columns,
        def: this.def,
        imageProperty: view.image,
        imageFit: view.imageFit ?? "cover",
        imageAspectRatio: view.imageAspectRatio ?? DEFAULT_CARD_ASPECT_RATIO,
        cardSize: view.cardSize ?? DEFAULT_CARD_SIZE,
        searchQuery: this.searchQuery,
      });
    } else {
      this.tableView.render(result, {
        columns,
        def: this.def,
        rowHeight: this.rowHeights.get(this.currentViewName) ?? "medium",
        searchQuery: this.searchQuery,
      });
    }
  }

  /**
   * Serializes concurrent `persist()` calls so two edits fired in quick
   * succession (e.g. a filter panel's property field committing, then its
   * value field committing a moment later) never race two overlapping
   * `vault.modify()` writes against each other — each queued write
   * re-reads `this.def` (already synchronously up to date by the time it
   * actually runs) rather than a stale snapshot from when it was queued.
   */
  private persistQueue: Promise<void> = Promise.resolve();

  /** Persist the in-memory definition back to the `.base` file and re-render immediately from that same in-memory state (see `lastKnownText`'s doc comment for why the resulting "modify" event(s) must not trigger a second, object-identity-breaking reload). */
  private persist(): Promise<void> {
    if (this.vaultSwitching) {
      this.persistRequestedWhileSuspended = true;
      return Promise.resolve();
    }
    this.persistQueue = this.persistQueue.catch(() => {}).then(() => this.doPersist());
    return this.persistQueue;
  }

  private async doPersist(): Promise<void> {
    if (!this.def || !this.file) return;
    const text = stringifyBaseFile(this.def);
    this.pendingKnownText = text;
    try {
      if (this.inlinePersist) await this.inlinePersist(text);
      else await this.app.vault.modify(this.file, text);
      this.lastKnownText = text;
    } finally {
      if (this.pendingKnownText === text) this.pendingKnownText = null;
    }
    this.runAndRender();
  }

  async prepareVaultSwitch(): Promise<void> {
    this.vaultSwitching = true;
    await this.persistQueue;
  }

  cancelVaultSwitch(): void {
    this.vaultSwitching = false;
    if (this.persistRequestedWhileSuspended) {
      this.persistRequestedWhileSuspended = false;
      void this.persist();
    }
  }

  async pauseAutosave(): Promise<void> {
    this.vaultSwitching = true;
    this.containerEl.inert = true;
    this.containerEl.setAttribute("aria-busy", "true");
    await this.persistQueue;
  }

  resumeAutosave(): void {
    this.containerEl.inert = false;
    this.bodyEl.inert = this.sourceConflictReadOnly;
    this.containerEl.removeAttribute("aria-busy");
    if (!this.sourceConflictReadOnly) this.cancelVaultSwitch();
  }

  // --- View menu ------------------------------------------------------

  private switchView(name: string): void {
    this.currentViewName = name;
    if (document.body.classList.contains("is-mobile") && this.file) {
      localStorage.setItem(`geode:bases-view:${encodeURIComponent(this.app.vault.root)}:${encodeURIComponent(this.file.path)}`, name);
    }
    this.runAndRender();
  }

  addView(type: "table" | "cards" = "table"): void {
    new PromptModal(this.app, {
      placeholder: "View name",
      onSubmit: (name) => {
        if (!this.def || this.def.views.some((v) => v.name === name)) return;
        this.def.views.push({ type, name });
        this.currentViewName = name;
        void this.persist();
      },
    }).open();
  }

  /** Change the current view's type (e.g. Table ↔ Cards), preserving its other settings. */
  private setViewType(type: "table" | "cards"): void {
    const view = this.currentView();
    if (!view || view.type === type) return;
    view.type = type;
    void this.persist();
  }

  private renameView(name: string): void {
    new PromptModal(this.app, {
      placeholder: "New view name",
      initialValue: name,
      onSubmit: (newName) => {
        if (!this.def || newName === name || this.def.views.some((v) => v.name === newName)) return;
        const view = this.def.views.find((v) => v.name === name);
        if (!view) return;
        view.name = newName;
        if (this.currentViewName === name) this.currentViewName = newName;
        void this.persist();
      },
    }).open();
  }

  private deleteView(name: string): void {
    if (!this.def || this.def.views.length <= 1) return;
    const idx = this.def.views.findIndex((v) => v.name === name);
    if (idx === -1) return;
    this.def.views.splice(idx, 1);
    if (this.currentViewName === name) this.currentViewName = this.def.views[0].name;
    void this.persist();
  }

  private moveView(name: string, dir: -1 | 1): void {
    if (!this.def) return;
    const idx = this.def.views.findIndex((v) => v.name === name);
    const target = idx + dir;
    if (idx === -1 || target < 0 || target >= this.def.views.length) return;
    [this.def.views[idx], this.def.views[target]] = [this.def.views[target], this.def.views[idx]];
    void this.persist();
  }

  // --- Filter panel -----------------------------------------------------

  private openFilterPanel(anchorEl: HTMLElement): void {
    if (!this.def) return;
    const view = this.currentView();
    if (!view) return;
    const scopes: FilterEditorScope[] = [
      {
        label: "All views",
        node: this.def.filters,
        onChange: (node) => {
          this.def!.filters = node;
          void this.persist();
        },
      },
      {
        label: "This view",
        node: view.filters,
        onChange: (node) => {
          view.filters = node;
          void this.persist();
        },
      },
    ];
    openFilterEditor(anchorEl, scopes, this.allPropertyPaths());
  }

  // --- Sort/group panel ---------------------------------------------------

  private openSortPanel(anchorEl: HTMLElement): void {
    const view = this.currentView();
    if (!view) return;
    const initial: SortGroupValue = { sort: view.sort ?? [], groupBy: view.groupBy ?? null };
    openSortGroupMenu(anchorEl, initial, this.allPropertyPaths(), (next) => {
      view.sort = next.sort.length ? next.sort : undefined;
      view.groupBy = next.groupBy ?? undefined;
      void this.persist();
    });
  }

  // --- Properties panel ---------------------------------------------------

  private openPropertiesPanel(anchorEl: HTMLElement): void {
    const view = this.currentView();
    if (!view || !this.def) return;
    const visible = this.lastColumns;
    const hidden = this.allPropertyPaths().filter((p) => !visible.includes(p));
    openPropertiesMenu(anchorEl, this.app, {
      visibleColumns: visible,
      hiddenColumns: hidden,
      onReorder: (next) => {
        view.order = next;
        void this.persist();
      },
      onHide: (path) => {
        view.order = visible.filter((p) => p !== path);
        void this.persist();
      },
      onShow: (path) => {
        view.order = [...visible, path];
        void this.persist();
      },
      onNewFormula: (name, expression) => {
        this.def!.formulas[name] = expression;
        view.order = [...visible, `formula.${name}`];
        void this.persist();
      },
    });
  }

  // --- Search / row height / new file --------------------------------------

  private setSearchQuery(query: string): void {
    this.searchQuery = query;
    const view = this.currentView();
    if (this.lastResult && this.def && view) {
      this.renderActiveView(view, this.lastResult, this.lastColumns);
    }
  }

  private setRowHeight(height: RowHeight): void {
    this.rowHeights.set(this.currentViewName, height);
    this.runAndRender();
  }

  private createNewFileInFolder(): void {
    if (!this.file) return;
    void this.app.createNewNote(this.file.parent);
  }

  // --- Cell editing ---------------------------------------------------------

  private editCell(file: TFile, columnPath: string, rawText: string): Promise<void> {
    const operation = this.commitCellEdit(file, columnPath, rawText);
    this.sourcePersistsInFlight.add(operation);
    operation.then(
      () => this.sourcePersistsInFlight.delete(operation),
      () => this.sourcePersistsInFlight.delete(operation),
    );
    return operation;
  }

  private async commitCellEdit(file: TFile, columnPath: string, rawText: string): Promise<void> {
    const key = frontmatterKeyForColumn(columnPath);
    if (!key) return;
    this.setSaveStatus("Saving Base…", false);
    this.sourceWritePath = file.path;
    try {
      await patchFrontmatter(this.app.vault, file, (fm) => {
        const value = parseEditedValue(rawText);
        if (value === undefined) delete fm[key];
        else fm[key] = value;
      });
      this.sourceEdit = null;
      this.setSaveStatus("Base saved", false);
      this.runAndRender();
    } catch (error) {
      this.setSaveStatus("Base save failed", true, async () => {
        await this.editCell(file, columnPath, rawText);
        this.tableView.acknowledgeEdit();
      });
      throw error;
    } finally {
      this.sourceWritePath = null;
    }
  }

  private beginSourceEdit(file: TFile, columnPath: string, rawText: string): void {
    this.sourceEdit = { file, columnPath, rawText, originalText: this.app.vault.read(file) };
  }

  async getDirtySourceConflict(path: string, folder = false): Promise<{ file: TFile; text: string } | null> {
    const edit = this.sourceEdit;
    if (!edit || (edit.file.path !== path && !(folder && edit.file.path.startsWith(`${path}/`)))) return null;
    const key = frontmatterKeyForColumn(edit.columnPath);
    if (!key) return null;
    const original = await edit.originalText;
    return {
      file: edit.file,
      text: patchFrontmatterText(original, (fm) => {
        const value = parseEditedValue(edit.rawText);
        if (value === undefined) delete fm[key];
        else fm[key] = value;
      }),
    };
  }

  presentSourceConflict(conflictPath: string | null, recoveryOnly = false): void {
    this.sourceConflictReadOnly = true;
    this.tableView.setReadOnly(true);
    this.bodyEl.inert = true;
    this.containerEl.querySelector(".bases-conflict-state")?.remove();
    const state = document.createElement("div");
    state.className = "bases-conflict-state";
    state.setAttribute("role", "status");
    state.textContent = recoveryOnly ? "Local Base edit retained for recovery." : "Provider and local Base edits were both preserved.";
    const providerPath = this.sourceEdit?.file.path;
    if (providerPath) {
      const provider = document.createElement("button");
      provider.type = "button";
      provider.textContent = "Open provider version";
      provider.addEventListener("click", () => {
        const file = this.app.vault.getFileByPath(providerPath);
        if (file) void this.app.openFile(file, true);
      });
      state.appendChild(provider);
    }
    if (conflictPath) {
      const local = document.createElement("button");
      local.type = "button";
      local.textContent = "Open local conflict copy";
      local.addEventListener("click", () => {
        const file = this.app.vault.getFileByPath(conflictPath);
        if (file) void this.app.openFile(file, true);
      });
      state.appendChild(local);
    }
    this.containerEl.appendChild(state);
    this.containerEl.dataset.basesConflictPath = conflictPath ?? "recovery";
  }

  private setSaveStatus(message: string, failed: boolean, retry?: () => Promise<void>): void {
    this.saveStatusEl.replaceChildren();
    this.saveStatusEl.setAttribute("role", failed ? "alert" : "status");
    if (!message) return;
    const text = document.createElement("span");
    text.textContent = message;
    this.saveStatusEl.appendChild(text);
    if (retry) {
      const button = document.createElement("button");
      button.type = "button";
      button.textContent = "Retry Base save";
      button.addEventListener("click", () => { void retry().catch(() => {}); });
      this.saveStatusEl.appendChild(button);
    }
  }

  // --- Copy / CSV export ----------------------------------------------------

  /**
   * The rows currently shown to the user for the active view: the query
   * result flattened across groups and filtered by the live search query, so
   * Copy/Export mirror exactly what's on screen.
   */
  private visibleRows(): QueryRow[] {
    if (!this.lastResult) return [];
    const flat = this.lastResult.groups
      ? this.lastResult.groups.flatMap((g) => g.rows)
      : this.lastResult.rows;
    if (!this.searchQuery) return flat;
    return flat.filter((row) =>
      matchesSearch(
        this.lastColumns.map((p) => {
          const v = row.properties[p];
          return v ? valueToDisplayString(v) : "";
        }),
        this.searchQuery
      )
    );
  }

  private async copyViewToClipboard(): Promise<void> {
    if (!this.def) return;
    const matrix = buildExportMatrix(this.visibleRows(), this.lastColumns, this.def);
    try {
      await navigator.clipboard.writeText(matrixToTsv(matrix));
    } catch {
      // Clipboard access denied/unavailable — silently no-op.
    }
  }

  private exportViewAsCsv(): void {
    if (!this.def || !this.file) return;
    const matrix = buildExportMatrix(this.visibleRows(), this.lastColumns, this.def);
    const csv = matrixToCsv(matrix);
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `${this.file.basename}.csv`;
    a.style.display = "none";
    document.body.appendChild(a);
    a.click();
    a.remove();
    // Revoke on the next tick so the click's download has captured the URL.
    setTimeout(() => URL.revokeObjectURL(url), 0);
  }
}

export { defaultBaseYaml };
