import { Marked } from "marked";
import type { App } from "../app";
import { TFile } from "../types";
import { getIconSvg } from "../api/icons";
import { calloutMeta, defaultCalloutTitle, parseCalloutHeader } from "./callout";
import { extractSection, loadEmbedBlobUrl, parseEmbedDims, resolveEmbed } from "./embed";
import { BaseView } from "../views/base-view";
import { CanvasView } from "../views/canvas-view";
import { replaceNthBaseBlock } from "../bases/embed-block";
import type {
  MarkdownPostProcessorContext,
  MarkdownRenderChild,
} from "./processor-registry";

function escapeHtml(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

/**
 * marked configuration shared by the block renderer (`MarkdownRenderer`) and
 * the inline one (`inlineHtml`), so a table cell and the same text in Reading
 * view can never be parsed under different options.
 */
const MARKED_OPTIONS = { gfm: true, breaks: true } as const;

/**
 * Instance backing `inlineHtml`. Kept at module scope (rather than on
 * `MarkdownRenderer`) so the inline path is a pure function of its arguments
 * and can be unit-tested without constructing an App.
 */
const inlineMarked = new Marked(MARKED_OPTIONS);

/**
 * The shared Obsidian inline-syntax pass: comments are stripped;
 * embeds/wikilinks/highlights/tags become HTML, with code regions protected
 * so none of those substitutions run inside them.
 *
 * Both rendering paths go through this one function so they cannot drift:
 * `preprocess()` (whole documents, Reading view / transclusions) and
 * `preprocessInline()` (a single inline fragment, e.g. one Live Preview table
 * cell). The only difference between them is what an `![[embed]]` becomes,
 * which is why that is injected as `renderEmbedTarget` rather than hard-coded.
 */
function applyInlineSyntax(
  src: string,
  sourcePath: string,
  app: App,
  renderEmbedTarget: (target: string, param: string) => string
): string {
  // Strip %%comments%%
  src = src.replace(/%%[\s\S]*?%%/g, "");

  // Protect code regions from inline substitution
  const codeBlocks: string[] = [];
  src = src.replace(/```[\s\S]*?(```|$)|`[^`\n]*`/g, (m) => {
    codeBlocks.push(m);
    return `�CODE${codeBlocks.length - 1}�`;
  });

  // Embeds ![[target]]
  src = src.replace(/!\[\[([^\[\]\n]+)\]\]/g, (_m, inner: string) => {
    const pipe = inner.indexOf("|");
    const target = (pipe === -1 ? inner : inner.slice(0, pipe)).trim();
    const param = pipe === -1 ? "" : inner.slice(pipe + 1).trim();
    return renderEmbedTarget(target, param);
  });

  // Wikilinks [[target|display]]
  src = src.replace(/\[\[([^\[\]\n]+)\]\]/g, (_m, inner: string) => {
    const pipe = inner.indexOf("|");
    const target = (pipe === -1 ? inner : inner.slice(0, pipe)).trim();
    const display = pipe === -1 ? target.replace(/#/g, " > ") : inner.slice(pipe + 1).trim();
    const dest = app.metadataCache.getFirstLinkpathDest(target, sourcePath);
    const cls = dest ? "internal-link" : "internal-link is-unresolved";
    return `<a class="${cls}" data-href="${escapeHtml(target)}" href="#">${escapeHtml(display)}</a>`;
  });

  // ==highlights==
  src = src.replace(/==([^=\n][^=]*?)==/g, "<mark>$1</mark>");

  // #tags
  src = src.replace(
    /(^|[\s(])#([A-Za-z0-9_\-\/\p{L}]*[A-Za-z_\-\/\p{L}][A-Za-z0-9_\-\/\p{L}]*)/gmu,
    (_m, pre: string, tag: string) =>
      `${pre}<a class="tag" data-tag="${escapeHtml(tag)}" href="#">#${escapeHtml(tag)}</a>`
  );

  // Restore code regions
  src = src.replace(/�CODE(\d+)�/g, (_m, i) => codeBlocks[Number(i)]);
  return src;
}

/**
 * Pre-process a whole Obsidian document into HTML placeholders before marked
 * runs: frontmatter is dropped (it is rendered separately as a properties
 * table), then the shared inline pass runs with full embed rendering.
 */
function preprocess(src: string, sourcePath: string, app: App): string {
  // Strip frontmatter (rendered separately as a properties table)
  src = src.replace(/^---\r?\n[\s\S]*?\r?\n---(\r?\n|$)/, "");
  return applyInlineSyntax(src, sourcePath, app, (target, param) =>
    renderEmbed(target, param, sourcePath, app)
  );
}

/**
 * Pre-process a *fragment* of Obsidian markdown — one Live Preview table
 * cell — with the same inline syntax as a full document, minus frontmatter
 * stripping (a fragment has none).
 *
 * `![[embeds]]` deliberately degrade to a plain `internal-link` anchor here.
 * The inline path runs no `postProcess`, so a transclusion / Bases / Canvas
 * mount would be a permanently broken stub, would resize the host widget
 * asynchronously after CodeMirror measured its height, and would leak
 * (`mountedBases` / `mountedCanvases` are torn down by `dispose(el)`, which
 * nothing calls for an inline fragment). Inline images in cells are a
 * reasonable follow-up, not part of this path's contract.
 */
export function preprocessInline(src: string, sourcePath: string, app: App): string {
  return applyInlineSyntax(src, sourcePath, app, (target) => {
    const dest = app.metadataCache.getFirstLinkpathDest(target, sourcePath);
    const cls = dest ? "internal-link" : "internal-link is-unresolved";
    return `<a class="${cls}" data-href="${escapeHtml(target)}" href="#">${escapeHtml(target)}</a>`;
  });
}

/**
 * Renders one inline markdown fragment to an HTML string, synchronously.
 *
 * Synchronous is a hard requirement, not a convenience: the only caller is
 * Live Preview's `TableWidget`, and any content that arrived later would
 * change the widget's height after CodeMirror had already measured it,
 * corrupting the height map. `marked.parseInline(..., { async: false })` is
 * typed `string` for exactly this reason; call-time options are merged with
 * the instance defaults, so `gfm`/`breaks` still apply.
 *
 * Never throws: a malformed fragment degrades to escaped plain text rather
 * than taking down the widget that is rendering it.
 */
export function inlineHtml(src: string, sourcePath: string, app: App): string {
  try {
    return inlineMarked.parseInline(preprocessInline(src, sourcePath, app), { async: false });
  } catch (err) {
    console.error("Failed to render inline markdown", err);
    return escapeHtml(src);
  }
}

function renderEmbed(target: string, param: string, sourcePath: string, app: App): string {
  const resolved = resolveEmbed(target, sourcePath, app);
  if (resolved.kind === "unresolved") {
    return `<span class="internal-embed is-unresolved">Unresolved embed: ${escapeHtml(target)}</span>`;
  }
  const dest = resolved.file!;
  if (dest.extension === "base") {
    // `![[File.base]]` embeds the first view; `![[File.base#ViewName]]` a
    // specific one. The BaseView is mounted async in postProcess.
    const viewName = resolved.subpath.startsWith("#") ? resolved.subpath.slice(1) : "";
    return `<div class="bases-embed-mount" data-base-path="${escapeHtml(dest.path)}" data-base-view="${escapeHtml(viewName)}"></div>`;
  }
  if (resolved.kind === "canvas") {
    return `<div class="canvas-embed-mount" data-canvas-path="${escapeHtml(dest.path)}"></div>`;
  }
  const src = `geode-file:${escapeHtml(dest.path)}`;
  if (resolved.kind === "image") {
    const { width, height } = parseEmbedDims(param);
    const style = width ? ` width="${width}"` + (height ? ` height="${height}"` : "") : "";
    return `<img class="internal-embed" data-path="${escapeHtml(dest.path)}" alt="${escapeHtml(dest.name)}"${style} src="${src}">`;
  }
  if (resolved.kind === "audio") {
    return `<audio class="internal-embed" controls data-path="${escapeHtml(dest.path)}" src="${src}"></audio>`;
  }
  if (resolved.kind === "video") {
    return `<video class="internal-embed" controls data-path="${escapeHtml(dest.path)}" src="${src}"></video>`;
  }
  if (resolved.kind === "note") {
    // Note embed rendered as a transclusion block; content filled in async after render.
    return `<div class="markdown-embed" data-path="${escapeHtml(dest.path)}" data-subpath="${escapeHtml(resolved.subpath)}"><div class="markdown-embed-title">${escapeHtml(dest.basename)}</div><div class="markdown-embed-content">Loading…</div></div>`;
  }
  return `<a class="internal-link" data-href="${escapeHtml(target)}" href="#">${escapeHtml(target)}</a>`;
}

/** Convert callout blockquotes (<blockquote><p>[!type] title ...) after marked. */
function transformCallouts(root: HTMLElement) {
  for (const bq of [...root.querySelectorAll("blockquote")]) {
    const first = bq.firstElementChild;
    if (!first || first.tagName !== "P") continue;
    const header = parseCalloutHeader(first.innerHTML);
    if (!header) continue;
    const { type, fold } = header;
    const title = header.title || defaultCalloutTitle(type);
    // The header regex stops at the first literal `<` (e.g. a `<br>` from
    // marked, or inline formatting), so anything after the matched prefix —
    // minus one leading `<br>` separating the title from the rest of the
    // paragraph — is the remaining callout body content.
    const rest = first.innerHTML.slice(header.raw.length).replace(/^<br>/, "");
    const meta = calloutMeta(type);
    const icon = getIconSvg(meta.icon) ?? "";

    const callout = document.createElement("div");
    callout.className = `callout callout-${meta.cssClass}`;
    callout.dataset.callout = type;
    const titleEl = document.createElement("div");
    titleEl.className = "callout-title";
    titleEl.innerHTML = `<span class="callout-icon">${icon}</span><span class="callout-title-inner">${title}</span>`;
    const content = document.createElement("div");
    content.className = "callout-content";
    if (rest.trim()) {
      const p = document.createElement("p");
      p.innerHTML = rest;
      content.appendChild(p);
    }
    let sib = first.nextElementSibling;
    while (sib) {
      const next = sib.nextElementSibling;
      content.appendChild(sib);
      sib = next;
    }
    callout.appendChild(titleEl);
    callout.appendChild(content);
    if (fold) {
      callout.classList.add("is-foldable");
      if (fold === "-") callout.classList.add("is-collapsed");
      titleEl.addEventListener("click", () => callout.classList.toggle("is-collapsed"));
    }
    transformCallouts(content); // nested callouts
    bq.replaceWith(callout);
  }
}

export class MarkdownRenderer {
  private marked: Marked;
  /**
   * Live embedded/transcluded BaseViews mounted under a given container, so
   * they can be torn down (vault listeners unregistered, cover blob URLs
   * revoked) before that container is re-rendered — otherwise every
   * re-render would leak another set of listeners.
   */
  private mountedBases = new WeakMap<HTMLElement, BaseView[]>();
  /** File-backed CanvasViews mounted under a Markdown render container. */
  private mountedCanvases = new WeakMap<HTMLElement, CanvasView[]>();
  /**
   * `MarkdownRenderChild`s attached by reading-view processors (via
   * `ctx.addChild`) under a given container, so they can be unloaded before
   * that container re-renders — mirroring `mountedBases`. Keyed by the same
   * render container the child was added under.
   */
  private mountedChildren = new WeakMap<HTMLElement, MarkdownRenderChild[]>();

  constructor(private app: App) {
    this.marked = new Marked(MARKED_OPTIONS);
  }

  /** Render markdown into el. Wires up link/tag clicks and embeds. */
  async render(src: string, el: HTMLElement, sourcePath: string): Promise<void> {
    this.dispose(el);
    const pre = preprocess(src, sourcePath, this.app);
    el.innerHTML = await this.marked.parse(pre);
    await this.postProcess(el, sourcePath);
  }

  /**
   * Renders one inline markdown fragment into `el`, synchronously and with no
   * post-processing — see `inlineHtml` for why both of those are required.
   *
   * Callers own click handling for the `internal-link` / `tag` anchors this
   * emits; unlike `render()`, no listener is attached here (Live Preview's
   * table widget delegates from its own root instead, because CodeMirror
   * never routes events into a widget whose `ignoreEvent()` is true).
   */
  renderInline(src: string, el: HTMLElement, sourcePath: string): void {
    el.innerHTML = inlineHtml(src, sourcePath, this.app);
  }

  /** Tear down any BaseViews previously mounted under `el`. */
  private disposeBases(el: HTMLElement): void {
    const list = this.mountedBases.get(el);
    if (!list) return;
    for (const view of list) view.onClose();
    this.mountedBases.delete(el);
  }

  /** Tear down embedded CanvasViews, including vault listeners and blob URLs. */
  private disposeCanvases(el: HTMLElement): void {
    const list = this.mountedCanvases.get(el);
    if (!list) return;
    for (const view of list) view.onClose();
    this.mountedCanvases.delete(el);
  }

  /** Dispose every lifecycle-bound child mounted by a Markdown render. */
  dispose(el: HTMLElement): void {
    this.disposeBases(el);
    this.disposeCanvases(el);
    this.disposeChildren(el);
  }

  /** Unload any processor-added `MarkdownRenderChild`s previously attached under `el`. */
  private disposeChildren(el: HTMLElement): void {
    const list = this.mountedChildren.get(el);
    if (!list) return;
    for (const child of list) child.unload();
    this.mountedChildren.delete(el);
  }

  /**
   * Renders a single `.md` note embed's body into contentEl — optionally
   * sliced to a `#Heading` subpath — then recursively post-processes it
   * (nested embeds, link/tag clicks, callouts, binary blob URLs) so a
   * transclusion behaves exactly like top-level content. Shared by Reading
   * view (via postProcess, below) and Live Preview's EmbedWidget
   * (src/renderer/markdown/live-preview.ts), so both use one render path
   * instead of duplicating transclusion logic.
   */
  async renderNoteEmbed(
    file: TFile,
    subpath: string,
    sourcePath: string,
    contentEl: HTMLElement
  ): Promise<void> {
    if (sourcePath === file.path) {
      // One-level recursion guard: catches direct self-embeds. A deeper
      // cycle (A embeds B, B embeds A) is not guarded — pre-existing
      // scope, unchanged by this refactor.
      contentEl.textContent = "Recursive embed";
      return;
    }
    this.dispose(contentEl);
    let text = await this.app.vault.cachedRead(file);
    if (subpath.startsWith("#") && !subpath.startsWith("#^")) {
      text = extractSection(text, subpath.slice(1));
    }
    const inner = preprocess(text, file.path, this.app);
    contentEl.innerHTML = await this.marked.parse(inner);
    await this.postProcess(contentEl, file.path);
  }

  private async postProcess(el: HTMLElement, sourcePath: string): Promise<void> {
    transformCallouts(el);

    // marked (GFM) renders task items as <li><input type=checkbox>; add the
    // classes our styles and Obsidian themes expect.
    for (const li of [...el.querySelectorAll("li")]) {
      const box = li.querySelector(":scope > input[type=checkbox]") as HTMLInputElement | null;
      if (box) {
        li.classList.add("task-list-item");
        if (box.checked) li.classList.add("is-checked");
      }
    }

    // Reading-view processors registered by plugins. The context is built once
    // and shared by the code-block dispatch below and the whole-document post
    // processors run at the end of this method.
    const ctx = this.buildProcessorContext(el, sourcePath);
    await this.runCodeBlockProcessors(el, ctx);

    el.addEventListener("click", (ev) => {
      const target = ev.target as HTMLElement;
      const link = target.closest("a.internal-link") as HTMLElement | null;
      if (link) {
        ev.preventDefault();
        this.app.openLink(link.dataset.href!, sourcePath, ev.metaKey || ev.ctrlKey);
        return;
      }
      const tag = target.closest("a.tag") as HTMLElement | null;
      if (tag) {
        ev.preventDefault();
        this.app.openSearch(`tag:${tag.dataset.tag}`);
        return;
      }
      const ext = target.closest("a[href^='http']") as HTMLAnchorElement | null;
      if (ext) {
        ev.preventDefault();
        // Honor the "Open external links in Geode" (Web Viewer) setting, matching
        // Live Preview and the global interceptor. Cmd/Ctrl-click always forces
        // the OS browser.
        if (ev.metaKey || ev.ctrlKey) window.geode.openExternal(ext.href);
        else this.app.openExternalLink(ext.href);
      }
    });

    // Resolve binary embeds to blob URLs
    const blobLoads = [...el.querySelectorAll<HTMLElement>("[data-path][src^='geode-file:']")].map(
      async (media) => {
        const file = this.app.vault.getFileByPath(media.dataset.path!);
        if (!file) return;
        (media as HTMLImageElement).src = await loadEmbedBlobUrl(this.app, file);
      }
    );

    // Fill in note transclusions (one level deep to avoid cycles)
    const noteEmbeds = [...el.querySelectorAll<HTMLElement>(".markdown-embed[data-path]")].map(
      async (embed) => {
        const file = this.app.vault.getFileByPath(embed.dataset.path!);
        const contentEl = embed.querySelector<HTMLElement>(".markdown-embed-content");
        if (!file || !contentEl) return;
        await this.renderNoteEmbed(file, embed.dataset.subpath ?? "", sourcePath, contentEl);
      }
    );

    const baseMounts = await this.mountBases(el, sourcePath);
    const canvasMounts = await this.mountCanvases(el, sourcePath);

    await Promise.all([...blobLoads, ...noteEmbeds]);
    if (baseMounts.length) this.mountedBases.set(el, baseMounts);
    if (canvasMounts.length) this.mountedCanvases.set(el, canvasMounts);

    // Whole-document post processors run last, over the fully-assembled DOM,
    // in ascending sortOrder.
    await this.runPostProcessors(el, ctx);
  }

  /**
   * Build the `MarkdownPostProcessorContext` shared by a single reading-view
   * render. Carries the real `sourcePath` + frontmatter, and an `addChild`
   * that loads each child and ties its lifecycle to `rootEl` (the render
   * container), so it's unloaded when that container next re-renders.
   */
  private buildProcessorContext(
    rootEl: HTMLElement,
    sourcePath: string
  ): MarkdownPostProcessorContext {
    const app = this.app;
    const file = sourcePath ? app.vault.getFileByPath(sourcePath) : null;
    const frontmatter = file ? app.metadataCache.getFileCache(file)?.frontmatter ?? null : null;
    return {
      sourcePath,
      frontmatter,
      addChild: (child) => {
        // Load the child so it renders, then track it under the render
        // container for teardown on the next render of `rootEl`.
        // PR1 SIMPLIFICATION: lifecycle is bound to the render container, not
        // the owning MarkdownView leaf. Reading view always re-renders through
        // the same container el, so container-scoped disposal is sufficient
        // here; a finer view-scoped binding (e.g. unload on leaf detach) is a
        // follow-up alongside live-preview support.
        child.load();
        let list = this.mountedChildren.get(rootEl);
        if (!list) {
          list = [];
          this.mountedChildren.set(rootEl, list);
        }
        list.push(child);
      },
      // Best-effort per Obsidian's contract (may return null). PR1 does not map
      // rendered DOM back to source line ranges; obsidian-tasks uses this only
      // to enhance inline `- [ ]` lines (they still render as plain checkboxes
      // without it). The ```tasks query code block does not depend on it.
      getSectionInfo: () => null,
    };
  }

  /**
   * Dispatch each fenced code block whose language has a registered processor:
   * replace the `<pre>` with a fresh container and invoke the processor with
   * the block's raw source text. `language-base` is intentionally not routed
   * here (it has no registered processor) and is still handled by
   * `mountBases`, so base blocks render exactly as before. Each processor runs
   * in its own try/catch so one failing block can't abort the whole render.
   */
  private async runCodeBlockProcessors(
    el: HTMLElement,
    ctx: MarkdownPostProcessorContext
  ): Promise<void> {
    const registry = this.app.markdownProcessors;
    if (!registry.hasCodeBlocks()) return;
    for (const code of [...el.querySelectorAll<HTMLElement>("pre > code")]) {
      const langClass = [...code.classList].find((c) => c.startsWith("language-"));
      if (!langClass) continue;
      const lang = langClass.slice("language-".length);
      const handler = registry.getCodeBlock(lang);
      if (!handler) continue;
      // `textContent` decodes the HTML entities marked escaped into the code
      // block, recovering the verbatim source — matching how `mountBases`
      // extracts a base block's YAML.
      const source = code.textContent ?? "";
      const container = document.createElement("div");
      const pre = code.parentElement!;
      pre.replaceWith(container);
      try {
        await handler(source, container, ctx);
      } catch (err) {
        console.error(`Error in '${lang}' markdown code block processor`, err);
      }
    }
  }

  /** Run whole-document post processors over `el` in ascending sortOrder, each isolated in a try/catch. */
  private async runPostProcessors(
    el: HTMLElement,
    ctx: MarkdownPostProcessorContext
  ): Promise<void> {
    for (const processor of this.app.markdownProcessors.postProcessorsInOrder()) {
      try {
        await processor(el, ctx);
      } catch (err) {
        console.error("Error in markdown post processor", err);
      }
    }
  }

  /**
   * Mount every Bases surface found in `el`: `![[File.base]]` transclusions
   * (`.bases-embed-mount` placeholders) and inline ```base code blocks
   * (`pre > code.language-base`). Returns the mounted views so `postProcess`
   * can register them for later teardown. Inline blocks persist edits back
   * into the host note's Nth base code block; the host note (`sourcePath`)
   * also supplies each base's `this` context and "New" folder.
   */
  private async mountBases(el: HTMLElement, sourcePath: string): Promise<BaseView[]> {
    const mounted: BaseView[] = [];
    const hostFile = this.app.vault.getFileByPath(sourcePath);

    // --- `![[File.base]]` / `![[File.base#View]]` transclusions ---
    for (const mount of el.querySelectorAll<HTMLElement>(".bases-embed-mount")) {
      const baseFile = this.app.vault.getFileByPath(mount.dataset.basePath!);
      if (!baseFile) continue;
      const view = new BaseView(this.app);
      view.onOpen();
      view.markEmbedded();
      await view.setFile(baseFile);
      if (mount.dataset.baseView) view.selectView(mount.dataset.baseView);
      mount.replaceWith(view.containerEl);
      mounted.push(view);
    }

    // --- inline ```base code blocks (interactive, persist to the note) ---
    if (hostFile) {
      const codeBlocks = [...el.querySelectorAll<HTMLElement>("pre > code.language-base")];
      for (let i = 0; i < codeBlocks.length; i++) {
        const code = codeBlocks[i];
        const yaml = code.textContent ?? "";
        const blockIndex = i;
        const view = new BaseView(this.app);
        view.onOpen();
        await view.mountInline(hostFile, yaml, async (newText) => {
          const cur = await this.app.vault.read(hostFile);
          await this.app.vault.modify(hostFile, replaceNthBaseBlock(cur, blockIndex, newText));
        });
        const pre = code.parentElement!;
        pre.replaceWith(view.containerEl);
        mounted.push(view);
      }
    }

    return mounted;
  }

  /** Mount resolved `![[File.canvas]]` placeholders as real, headerless CanvasViews. */
  private async mountCanvases(el: HTMLElement, sourcePath: string): Promise<CanvasView[]> {
    const mounted: CanvasView[] = [];
    for (const mount of el.querySelectorAll<HTMLElement>(".canvas-embed-mount")) {
      const canvasFile = this.app.vault.getFileByPath(mount.dataset.canvasPath!);
      if (!canvasFile) continue;
      let ancestor = mount.parentElement?.closest<HTMLElement>(".canvas-embed-view") ?? null;
      let recursive = sourcePath === canvasFile.path;
      while (ancestor && !recursive) {
        recursive = ancestor.dataset.canvasPath === canvasFile.path;
        ancestor = ancestor.parentElement?.closest<HTMLElement>(".canvas-embed-view") ?? null;
      }
      if (recursive) {
        const message = document.createElement("div");
        message.className = "canvas-embed-cycle";
        message.textContent = `Recursive Canvas embed: ${canvasFile.basename}`;
        mount.replaceWith(message);
        continue;
      }
      const view = new CanvasView(this.app);
      view.markEmbedded();
      view.onOpen();
      try {
        await view.setFile(canvasFile);
      } catch {
        view.onClose();
        const message = document.createElement("div");
        message.className = "canvas-embed-cycle is-unresolved";
        message.textContent = `Unable to load Canvas: ${canvasFile.basename}`;
        mount.replaceWith(message);
        continue;
      }
      mount.replaceWith(view.containerEl);
      mounted.push(view);
    }
    return mounted;
  }
}
